UPDATE public.email_templates
SET body_template = 'Bonjour {{prenom}},<br><br>Vous trouverez ci-joint, en pièces jointes, deux documents à <strong>étudier et vous entraîner à remplir</strong> avant votre <strong>examen pratique VTC</strong> :<br><br>📄 <strong>Modèle de devis</strong> (Modele_Devis_Examen_VTC.pdf)<br>🧾 <strong>Modèle de facture</strong> (Modele_Facture_Examen_VTC.pdf)<br><br>⚠️ <strong>Important :</strong> le jour de l''examen, c''est <strong>le jury</strong> qui vous remettra le devis et la facture vierges à compléter. Vous n''avez donc <strong>pas besoin de les imprimer</strong> ni de les apporter avec vous.<br><br>Ces modèles vous sont envoyés uniquement pour que vous puissiez :<br><br>• Vous <strong>familiariser avec le format</strong> exact attendu par le jury.<br>• Vous <strong>entraîner à les remplir correctement</strong> (tarif, trajet, client, TVA, mentions obligatoires, etc.).<br>• Arriver le jour J <strong>parfaitement à l''aise</strong> avec ce type de document.<br><br>Pensez simplement à avoir un <strong>stylo</strong> sur vous le jour de l''épreuve.<br><br>Si vous avez la moindre question, n''hésitez pas à nous contacter.<br><br>Bon courage pour votre examen !<br><br>Cordialement,<br><strong>L''équipe FTransport</strong><br>📞 09 70 70 99 60<br>✉️ contact@ftransport.fr'
WHERE id = 'modeles-devis-facture-examen-vtc';